CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200) NOT NULL,prompt TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lessons(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,unit_idx INT NOT NULL,unit_title VARCHAR(200),title VARCHAR(200) NOT NULL,content LONGTEXT NULL,completed_at DATETIME NULL,score INT NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS answers(id INT AUTO_INCREMENT PRIMARY KEY,lesson_id INT NOT NULL,quiz_idx INT NOT NULL,chosen INT NOT NULL,is_correct TINYINT NOT NULL,answered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(lesson_id,quiz_idx),FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
